function safeImageSrc(value){const raw=String(value??'').trim();if(/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/]+={0,2}$/i.test(raw))return esc(raw);if(/^https:\/\/[^\s"'<>]+$/i.test(raw))return esc(raw);return ''}
