/* Short tap pulse for icons and buttons. The Android shell in this repo is a
   Trusted Web Activity (io.github.bvsquiat27.twa) with no JS haptics bridge,
   so this uses the Vibration API. navigator.vibrate is missing on iOS Safari. */
const HAPTIC_KEY='msb_tap_vibration';
const HAPTIC_MS=10;
const HAPTIC_GAP=80;
let hapticAt=0;
function hapticOn(){try{return localStorage.getItem(HAPTIC_KEY)!=='off'}catch{return true}}
function setHaptic(on){try{localStorage.setItem(HAPTIC_KEY,on?'on':'off')}catch{}}
function haptic(){
  if(!hapticOn())return;
  const now=typeof performance!=='undefined'&&performance.now?performance.now():Date.now();
  if(now-hapticAt<HAPTIC_GAP)return;
  hapticAt=now;
  try{if(typeof navigator!=='undefined'&&typeof navigator.vibrate==='function')navigator.vibrate(HAPTIC_MS)}catch{}
}
function hapticStrong(){
  if(!hapticOn())return;
  hapticAt=typeof performance!=='undefined'&&performance.now?performance.now():Date.now();
  try{if(typeof navigator!=='undefined'&&typeof navigator.vibrate==='function')navigator.vibrate([35,40,90])}catch{}
}
window.haptic=haptic;
window.hapticStrong=hapticStrong;
function hapticControl(node){
  const el=node&&node.nodeType===1?node:node&&node.parentElement;
  if(!el||typeof el.closest!=='function')return null;
  if(el.closest('input,textarea,select,option,[contenteditable="true"]'))return null;
  const button=el.closest('button,[role="button"],[role="switch"]');
  if(!button||button.disabled||button.getAttribute('aria-disabled')==='true')return null;
  if(button.classList.contains('bible-verse')||button.closest('.bible-verses'))return null;
  if(button.hasAttribute('data-rope-tap'))return null;
  if(button.hasAttribute('data-haptic-self'))return null;
  const link=el.closest('a');
  if(link&&(link===button||button.contains(link))&&link.closest('.bible-page,.bible-study-card,.passage,.study-copy,.bible-verses'))return null;
  return button;
}
function hapticSettingHtml(){
  const on=hapticOn();
  return `<section class="card tap-vibration"><div class="tap-vibration-copy"><span class="eyebrow">TOUCH</span><h2>Tap vibration</h2><p class="muted">A short pulse when you tap icons and buttons.</p></div><button type="button" class="tap-vibration-toggle" data-action="haptic-toggle" role="switch" aria-checked="${on}" aria-label="Tap vibration"><span class="tap-vibration-knob" aria-hidden="true"></span><span class="tap-vibration-state">${on?'On':'Off'}</span></button></section>`;
}
let hapticPointer=null,hapticSuppressClick=false;
document.addEventListener('pointerdown',event=>{
  if(event.button&&event.button!==0){hapticPointer=null;return}
  const control=hapticControl(event.target);
  hapticPointer=control?{id:event.pointerId,x:event.clientX,y:event.clientY,moved:false}:null;
},true);
document.addEventListener('pointermove',event=>{
  if(!hapticPointer||event.pointerId!==hapticPointer.id||hapticPointer.moved)return;
  if(Math.hypot(event.clientX-hapticPointer.x,event.clientY-hapticPointer.y)>12)hapticPointer.moved=true;
},true);
document.addEventListener('pointerup',event=>{
  if(!hapticPointer||event.pointerId!==hapticPointer.id)return;
  if(hapticPointer.moved){hapticSuppressClick=true;setTimeout(()=>{hapticSuppressClick=false},0)}
},true);
document.addEventListener('pointercancel',()=>{hapticPointer=null},true);
document.addEventListener('click',event=>{
  if(hapticSuppressClick){hapticSuppressClick=false;return}
  if(event.button&&event.button!==0)return;
  if(hapticControl(event.target))haptic();
},true);
function toast(message){const el=$('#toast');const text=window.MsbI18n?MsbI18n.t(String(message??'')):message;el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500)}
async function apiRemote(path,method='GET',body){const form=body instanceof FormData,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),form?60000:25000);try{const res=await fetch(API+path,{method,credentials:'same-origin',signal:controller.signal,headers:{...(body!==undefined&&!form?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:'Bearer '+state.token}:{})},...(body===undefined?{}:{body:form?body:JSON.stringify(body)})});const raw=await res.text();let data=null;try{data=raw?JSON.parse(raw):{}}catch{data=null}if(controller.signal.aborted)throw Error('Timed out');if(data===null||typeof data!=='object'){const failure=Error('The account service did not answer.');failure.status=res.ok?404:res.status;failure.invalid=true;throw failure}if(!res.ok){const failure=Error(data.error||`Request failed (${res.status})`);failure.status=res.status;throw failure}return data}catch(error){if(controller.signal.aborted)throw Error(path==='/auth/register'?'The request timed out. Your account may exist. Try signing in before trying signup again.':'The request timed out. Check your connection and try again.');if(error instanceof TypeError){const failure=Error('Could not reach Mind Soul & Body. Check your connection and try again.');failure.offline=true;throw failure}throw error}finally{clearTimeout(timer)}}
