async function loadAccount(){const [profile,dashboard]=await Promise.all([api('/me'),api('/study/dashboard')]);state.profile=profile;const legacyTheme=localStorage.getItem('msb_theme');applyTheme(localStorage.getItem(themeKey())||localStorage.getItem('msb_theme:device')||legacyTheme||'teal');if(legacyTheme)localStorage.removeItem('msb_theme');state.progress=dashboard.progress||[];state.notes=dashboard.notes||[];state.challengeProgress=dashboard.challenges||[];BibleReader.resetAccount();$('#account-button').innerHTML=avatar()}
