function msbCategoryEs(value){return MSB_CATEGORY_ES[value]||value||''}
function msbLevelEs(value){return String(value||'').replace(/(\d+) teaching cards?/gi,(m,n)=>n==='1'?'1 tarjeta de enseñanza':n+' tarjetas de enseñanza').replace(/(\d+) questions?/gi,(m,n)=>n==='1'?'1 pregunta':n+' preguntas').replace(/(\d+) readings?/gi,(m,n)=>n==='1'?'1 lectura':n+' lecturas').replace(/Match the Word/gi,'Empareja la Palabra').replace(/(\d+) quick steps?/gi,(m,n)=>n==='1'?'1 paso rápido':n+' pasos rápidos').replace(/(\d+) steps?/gi,(m,n)=>n==='1'?'1 paso':n+' pasos').replace(/Session (\d+) of (\d+)/gi,'Sesión $1 de $2').replace(/Deep dive/gi,'A fondo').replace(/^Advanced$/i,'Avanzado').replace(/^Intermediate$/i,'Intermedio').replace(/^Foundations$/i,'Fundamentos').replace(/^Beginner$/i,'Principiante')}
function markEn(text){const value=String(text||'');if(!msbEs()||!value||value.includes('(en inglés)'))return value;return value+'\n\n(en inglés)'}
const MSB_BOOK_ES={"Genesis":"Génesis","Exodus":"Éxodo","Leviticus":"Levítico","Numbers":"Números","Deuteronomy":"Deuteronomio","Joshua":"Josué","Judges":"Jueces","Ruth":"Rut","1 Kings":"1 Reyes","2 Kings":"2 Reyes","1 Chronicles":"1 Crónicas","2 Chronicles":"2 Crónicas","Ezra":"Esdras","Nehemiah":"Nehemías","Esther":"Ester","Psalms":"Salmos","Proverbs":"Proverbios","Ecclesiastes":"Eclesiastés","Song of Solomon":"Cantar de los Cantares","Isaiah":"Isaías","Jeremiah":"Jeremías","Lamentations":"Lamentaciones","Ezekiel":"Ezequiel","Hosea":"Oseas","Amos":"Amós","Obadiah":"Abdías","Jonah":"Jonás","Micah":"Miqueas","Nahum":"Nahúm","Habakkuk":"Habacuc","Zephaniah":"Sofonías","Haggai":"Hageo","Zechariah":"Zacarías","Malachi":"Malaquías","Matthew":"Mateo","Mark":"Marcos","Luke":"Lucas","John":"Juan","Acts":"Hechos","Romans":"Romanos","1 Corinthians":"1 Corintios","2 Corinthians":"2 Corintios","Galatians":"Gálatas","Ephesians":"Efesios","Philippians":"Filipenses","Colossians":"Colosenses","1 Thessalonians":"1 Tesalonicenses","2 Thessalonians":"2 Tesalonicenses","1 Timothy":"1 Timoteo","2 Timothy":"2 Timoteo","Titus":"Tito","Philemon":"Filemón","Hebrews":"Hebreos","James":"Santiago","1 Peter":"1 Pedro","2 Peter":"2 Pedro","1 John":"1 Juan","2 John":"2 Juan","3 John":"3 Juan","Jude":"Judas","Revelation":"Apocalipsis","Psalm":"Salmo"};
const MSB_BOOK_RE=new RegExp('^(\\s*)('+Object.keys(MSB_BOOK_ES).sort((a,b)=>b.length-a.length).map(n=>n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?=\\s+\\d)');
