function viewStudy(item){if(!item||!msbEs())return item;return Object.assign({},item,{reference:item.referenceEs||msbRefEs(item.reference),title:item.titleEs||item.title,theme:item.themeEs||item.theme,passage:item.passageEs||markEn(item.passage),context:item.contextEs||markEn(item.context),orthodox:item.orthodoxEs||markEn(item.orthodox),practice:item.practiceEs||markEn(item.practice),questions:item.questionsEs||(item.questions||[]).map(q=>typeof q==='string'&&!q.includes('(en inglés)')?q+' (en inglés)':q),quiz:item.quizEs||(item.quiz||[]).map(q=>Object.assign({},q,{prompt:q.prompt&&!String(q.prompt).includes('(en inglés)')?q.prompt+' (en inglés)':q.prompt}))})}
