function section(title,action=''){return `<div class="section-head"><h2>${esc(title)}</h2>${action}</div>`}
function msbDragRounds(item){const refs=item?.drag?.refs||[];if(!refs.length)return[];return[{label:'Round 1 · full text',showText:true,refs},{label:'Round 2 · reference only',showText:false,refs:[...refs].reverse()}]}
function msbDragInit(run,item){run.drag={round:0,placed:{},selected:null,mistakes:0,correct:0,total:msbDragRounds(item).reduce((sum,round)=>sum+round.refs.length,0),feedback:''};run.phase='drag'}
function msbDragHtml(item,run){const rounds=msbDragRounds(item);if(!rounds.length||!run.drag)return'';const round=rounds[Math.min(run.drag.round,rounds.length-1)],items=round.refs,placed=run.drag.placed||{},allPlaced=items.every(ref=>placed[ref.ref]),byCat={};for(const ref of items){if(placed[ref.ref]){(byCat[placed[ref.ref]]??=[]).push(ref)}}return `<section class="card drag-card"><span class="eyebrow">MATCH THE WORD · ${esc(round.label.toUpperCase())}</span><h2>${esc(item.drag.title||'Match the Word')}</h2><p>${esc(item.drag.intro||'Drag each verse to the claim it guards.')}</p><p class="drag-roundline">${round.showText?'Full text round: read the words, then place the verse.':'Reference only: the text has faded. Trust the reference you learned.'} ${items.filter(ref=>placed[ref.ref]).length}/${items.length} placed · ${run.drag.correct}/${run.drag.total} total</p><div class="drag-bank" aria-label="Verses to place">${items.filter(ref=>!placed[ref.ref]).map(ref=>`<button type="button" class="drag-chip ${run.drag.selected===ref.ref?'selected':''}" draggable="true" data-drag-chip="${esc(ref.ref)}"><strong>${esc(ref.ref)}</strong>${round.showText?`<span>${esc(ref.text)}</span>`:''}</button>`).join('')||'<p class="drag-empty">All verses placed for this round.</p>'}</div><div class="drag-buckets">${item.drag.categories.map(cat=>`<section class="drag-bucket" data-drag-bucket="${esc(cat.id)}"><h3>${esc(cat.label)}</h3>${(byCat[cat.id]||[]).map(ref=>`<span class="drag-placed">✓ ${esc(ref.ref)}</span>`).join('')||'<span class="drag-bucket-hint">Drop here</span>'}</section>`).join('')}</div>${run.drag.feedback?`<div class="drag-feedback" role="status">${esc(run.drag.feedback)}</div>`:''}<button class="primary" data-drag-next ${allPlaced?'':'disabled'}>${run.drag.round+1<rounds.length?'Next round':'Finish lesson'}</button></section>`}
function msbDragPlace(run,item,refLabel,catId){const rounds=msbDragRounds(item);if(!rounds.length||!run.drag)return false;const round=rounds[Math.min(run.drag.round,rounds.length-1)],ref=round.refs.find(entry=>entry.ref===refLabel);if(!ref||run.drag.placed[ref.ref])return false;if(ref.category===catId){run.drag.placed[ref.ref]=catId;run.drag.selected=null;run.drag.correct++;run.drag.feedback=`${ref.ref} belongs there. ${round.refs.filter(entry=>run.drag.placed[entry.ref]).length}/${round.refs.length} placed this round.`}else{run.drag.mistakes++;run.drag.selected=ref.ref;run.drag.feedback=`Not there. Ask what the verse is guarding, then try again: ${ref.ref}.`}return true}
function msbDragClick(event){const chip=event.target.closest('[data-drag-chip]');const bucket=event.target.closest('[data-drag-bucket]');const next=event.target.closest('[data-drag-next]');if(state.screen!=='mini'||!state.mini||state.mini.phase!=='drag')return;const run=state.mini,item=state.challenges.find(entry=>entry.id===run.id);if(!item||!run.drag)return;if(chip){run.drag.selected=chip.dataset.dragChip;miniScreen();return}if(bucket&&run.drag.selected){if(msbDragPlace(run,item,run.drag.selected,bucket.dataset.dragBucket))miniScreen();return}if(next){event.preventDefault();const rounds=msbDragRounds(item);if(run.drag.round+1<rounds.length){run.drag.round++;run.drag.placed={};run.drag.selected=null;run.drag.feedback='';miniScreen();return}run.done=true;run.phase='done';run.dragSummary=`Match the Word: ${run.drag.correct}/${run.drag.total} placed · ${run.drag.mistakes} ${run.drag.mistakes===1?'miss':'misses'}`;miniScreen();saveMini(run)}}
function msbDragStart(event){const chip=event.target.closest('[data-drag-chip]');if(!chip||!event.dataTransfer)return;event.dataTransfer.setData('text/plain',chip.dataset.dragChip);event.dataTransfer.effectAllowed='move';if(state.mini)state.mini.drag.selected=chip.dataset.dragChip}
function msbDragOver(event){const bucket=event.target.closest('[data-drag-bucket]');if(!bucket)return;event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='move';bucket.classList.add('over')}
function msbDragLeave(event){const bucket=event.target.closest('[data-drag-bucket]');if(bucket)bucket.classList.remove('over')}
function msbDragDrop(event){const bucket=event.target.closest('[data-drag-bucket]');if(!bucket||state.screen!=='mini'||!state.mini||state.mini.phase!=='drag')return;event.preventDefault();bucket.classList.remove('over');const run=state.mini,item=state.challenges.find(entry=>entry.id===run.id);const ref=event.dataTransfer?.getData('text/plain')||run.drag?.selected;if(item&&ref&&msbDragPlace(run,item,ref,bucket.dataset.dragBucket))miniScreen()}
function quizHeading(count){if(msbEs()){const es=['','Una','Dos','Tres','Cuatro','Cinco','Seis','Siete','Ocho','Nueve','Diez'];return count===1?'Una pregunta corta':`${es[count]||count} preguntas cortas`}const words=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten'];const word=words[count]||String(count);return count===1?'One short question':`${word} short questions`}
function msbChapterButton(item){const first=String(item?.reference||'').split(';')[0].trim();if(!/^(.+?)\s+\d+/.test(first))return '';return `<button class="text-button" data-bible-open="${esc(item.id)}">Read the full chapter in the Bible ↗</button>`}
function msbProse(text){return String(text||'').split(/\n\n+/).map(part=>part.trim()).filter(Boolean).map(part=>`<p>${esc(part)}</p>`).join('')}
function msbLessonAt(item,index){const lessons=item?.lessons||[];const tagged=lessons.find(lesson=>Number.isInteger(lesson.step)&&lesson.step===index);if(tagged)return tagged;const at=lessons[index];if(!at||Number.isInteger(at.step))return null;return at}
function msbReadAloud(){return `<div class="speech-row"><button type="button" class="secondary" data-read-play>Read aloud</button><button type="button" class="secondary" data-speech-pause>Pause</button><button type="button" class="secondary" data-speech-stop>Stop</button>${window.MsbSpeech?MsbSpeech.rateHtml():''}</div>`}
function msbLocalExplanation(item,index){if(!msbEs()||!item)return '';const question=item.questionsEs&&item.questionsEs[index];return question?(question.explanationEs||question.explanation||''):''}
document.addEventListener('click',event=>{const play=event.target.closest('[data-read-play]');if(!play||!window.MsbSpeech)return;const block=play.closest('[data-read-block]');if(!block)return;const nodes=[...block.querySelectorAll('h2, p')].filter(el=>el.textContent.trim()&&!el.closest('.speech-row'));MsbSpeech.speak({lang:msbEs()?'es':'en',chunks:nodes.map(el=>({text:el.textContent.trim(),el})),onChunk:chunk=>{if(chunk.el)chunk.el.scrollIntoView({block:'nearest'})}})});
function msbTeachingCard(lesson){if(!lesson)return'';return `<section class="card mini-teaching" data-read-block><span class="eyebrow">READ FIRST</span><h2>${esc(lesson.heading)}</h2>${msbProse(lesson.body)}${msbReadAloud()}</section>`}
function msbSourceLine(item){if(!item?.source)return'';return `<p class="small">Based on ${item.sourceUrl?`<a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(item.source)} ↗</a>`:esc(item.source)}</p>`}
function msbAdaptationNote(item){if(!item?.adaptation)return'';return `<p class="small adaptation-note">Adapted from The Mystery of Faith by Bishop Hilarion Alfeyev.</p>`}
function welcome(){screen.innerHTML=`<span class="eyebrow">SCRIPTURE · PRAYER · TRADITION</span><h1>Read deeply. Live faithfully.</h1><p class="lead">Read Scripture with the Orthodox Church. A profile on this device keeps your notes and progress in this browser.</p>${weeklyDashboard()}<div class="card welcome-action"><h2>Keep your place</h2><p>Create a profile to save notes, reading progress, and highlights in this browser. They stay on this device.</p><button class="primary" data-action="signup">Create your study profile</button> <button class="secondary" data-action="signin">Sign in</button></div><div class="home-actions"><button class="hub-card" data-nav="bible"><span class="eyebrow">READ</span><strong>The full Bible</strong><span>78 books, notes, and highlights</span></button><button class="hub-card" data-nav="challenges"><span class="eyebrow">PLAY</span><strong>Games</strong><span>Survey Says, Jeopardy, and lessons</span></button><button class="hub-card" data-nav="stories"><span class="eyebrow">LITTLE ONES</span><strong>Stories for little ones</strong><span>Short Bible stories to read aloud</span></button><button class="hub-card" data-nav="love"><span class="eyebrow">FOR SOMEONE YOU LOVE</span><strong>Love in Scripture</strong><span>Verses to send to your person</span></button><button class="hub-card" data-nav="memory"><span class="eyebrow">LEARN BY HEART</span><strong>Memory verse</strong><span>A verse that fades until you know it</span></button><button class="hub-card" data-nav="study-together"><span class="eyebrow">TOGETHER</span><strong>Study together</strong><span>A private notebook with a friend</span></button></div>${section('Start with Scripture')}<div class="lesson-grid">${state.studies.slice(0,4).map(lessonCard).join('')}</div><p class="footnote">The study notes are original summaries, not quotations from the Church Fathers or a substitute for guidance from your parish.</p>`;if(window.MsbDay)MsbDay.hydrate()}
function msbReadingStreak(store){const days=new Set();for(const log of (store?.readLog||[]))if(log?.ts)days.add(new Date(log.ts*1000).toDateString());for(const item of (store?.progress||[]))if(item?.completed_at)days.add(new Date(item.completed_at*1000).toDateString());let streak=0;const day=new Date();day.setHours(0,0,0,0);if(!days.has(day.toDateString()))day.setDate(day.getDate()-1);while(days.has(day.toDateString())){streak++;day.setDate(day.getDate()-1)}return streak}
function studyWeek(){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-start.getDay());const days=Array(7).fill(0),types=[0,0,0,0];for(const item of state.progress){if(!item.completed_at)continue;const when=new Date(item.completed_at*1000);if(when<start||when>now)continue;days[when.getDay()]++;const ref=study(item.study_id)?.reference||'';types[/^(John|Matthew|Luke|Mark)/.test(ref)?0:/^Psalm/.test(ref)?1:/^(James|1 Corinthians|2 Corinthians|Romans)/.test(ref)?2:3]++}for(const log of (msbStore().readLog||[])){if(!log.ts)continue;const when=new Date(log.ts*1000);if(when<start||when>now)continue;days[when.getDay()]++;types[log.book_id>=40&&log.book_id<=43?0:log.book_id===19?1:log.book_id>=45&&log.book_id<=65?2:3]++}const streak=msbReadingStreak(msbStore());return {days,types,streak,total:days.reduce((a,b)=>a+b,0)}}
function dailyCard(){const date=new Date();return date.getDay()%2?{book:43,chapter:1,verse:5,name:'John 1:5',text:'And the light shineth in darkness; and the darkness comprehended it not.'}:{book:19,chapter:119,verse:105,name:'Psalm 119:105',text:'Thy word is a lamp unto my feet, And a light unto my path.'}}

function weeklyDashboard(){const week=studyWeek(),verse=dailyCard(),total=state.studies.length,percent=total?Math.round(completed()/total*100):0;const labels=['Gospels','Psalms','Letters','Other plans'],colors=['var(--teal)','var(--chart-warm)','var(--chart-cool)','var(--ink-soft)'];let angle=0;const parts=week.types.map((value,i)=>{const begin=angle;angle+=week.total?value/week.total*360:0;return value?`${colors[i]} ${begin}deg ${angle}deg`:''}).filter(Boolean);const ring=parts.length?`conic-gradient(${parts.join(',')})`:'conic-gradient(var(--surface2) 0deg 360deg)';return `${window.MsbMoments?MsbMoments.slot():''}${window.MsbBridge?MsbBridge.homeInbox():''}${window.MsbDay?MsbDay.slot(verse):`<section class="daily-stack" id="orthodox-day"><span class="eyebrow">TODAY IN SCRIPTURE</span><h2>${esc(verse.text||'')}</h2><span>${esc(verse.name)}</span><button class="verse-play" data-daily-read aria-label="Open today’s verse in the Bible"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m9 6 9 6-9 6z"/></svg></button></section>`}<div class="neon-stats"><section class="neon-stat violet"><span class="eyebrow">READING STREAK</span><strong>${week.streak}</strong><span>${week.streak===1?'day':'days'} in the Word</span></section><section class="neon-stat mint"><span class="eyebrow">THIS WEEK</span><strong>${week.total}</strong><span>${week.total===1?'reading':'readings'} logged</span></section></div><div class="insights-grid"><section class="card week-panel"><div class="panel-top"><h2>This week</h2><span>${(window.MsbI18n&&MsbI18n.lang()==='es')?(week.total===1?'1 completado':week.total+' completados'):(week.total+' '+(week.total===1?'completion':'completions'))}</span></div><div class="week-bars" role="img" aria-label="Readings logged Sunday through Saturday: ${week.days.join(', ')}"><div class="bar-lines" aria-hidden="true"></div>${week.days.map((count,i)=>`<div class="bar-day"><i style="height:${count?Math.round(count/Math.max(1,...week.days)*100):0}%"></i><small>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]}</small></div>`).join('')}</div></section><section class="card split-panel"><h2>Reading split</h2><p class="small">Chapters logged + studies completed this week</p><div class="donut" style="--donut:${ring}" role="img" aria-label="This week’s reading split"><div><strong>${week.total}</strong><span>chapters</span></div></div><div class="split-legend">${labels.map((label,i)=>`<span><i style="background:${colors[i]}"></i>${label}<b>${week.total?Math.round(week.types[i]/week.total*100):0}%</b></span>`).join('')}</div></section></div><section class="progress-orb card"><h2>It's all about progress,<br>not perfection.</h2><div class="orb" aria-hidden="true"></div><strong>${percent}%</strong><span>of these studies complete</span></section>`}
function today(){if(!state.user)return welcome();const nextRaw=state.studies.find(item=>!progress(item.id)?.completed_at)||state.studies[0];const next=nextRaw?viewStudy(nextRaw):null;screen.innerHTML=`<span class="eyebrow">TODAY</span><h1>${(window.MsbI18n&&MsbI18n.lang()==='es')?`La paz sea contigo, ${esc(state.profile?.name?.split(' ')[0]||'amiga')}.`:`Peace to you, ${esc(state.profile?.name?.split(' ')[0]||'friend')}.`}</h1>${!state.user.registered?'<div class="card"><p>Your guest space is temporary. Create an account to keep your notes in this browser.</p><button class="primary" data-action="signup">Create account</button></div>':''}${weeklyDashboard()}<section class="card next-study"><div><span class="eyebrow">${completed()===state.studies.length?'RETURN TO THE WORD':'UP NEXT'}</span><h2>${esc(next.title)}</h2><p>${esc(next.reference)} · ${esc(next.theme)}</p></div><button class="primary" data-lesson="${esc(next.id)}">${completed()===state.studies.length?'Read again':'Continue reading'}</button></section><div class="home-actions"><button class="hub-card" data-nav="bible"><span class="eyebrow">READ</span><strong>The full Bible</strong><span>78 books, notes, and highlights</span></button><button class="hub-card" data-nav="challenges"><span class="eyebrow">PLAY</span><strong>Games</strong><span>Survey Says, Jeopardy, and lessons</span></button><button class="hub-card" data-nav="stories"><span class="eyebrow">LITTLE ONES</span><strong>Stories for little ones</strong><span>Short Bible stories to read aloud</span></button><button class="hub-card" data-nav="love"><span class="eyebrow">FOR SOMEONE YOU LOVE</span><strong>Love in Scripture</strong><span>Verses to send to your person</span></button><button class="hub-card" data-nav="memory"><span class="eyebrow">LEARN BY HEART</span><strong>Memory verse</strong><span>A verse that fades until you know it</span></button><button class="hub-card" data-nav="study-together"><span class="eyebrow">TOGETHER</span><strong>Study together</strong><span>A private notebook with a friend</span></button></div>${window.MsbTools?MsbTools.home():''}<p class="footnote">Study notes are a learning aid. Bring difficult questions to your pastor or study group.</p>`;if(window.MsbDay)MsbDay.hydrate()}
