function showFormError(form,message){let el=form.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.prepend(el)}el.hidden=false;el.textContent=message;el.scrollIntoView({block:'nearest'})}
