async function boot(){msbRequestPersist();try{const [library,config,session,challengeLibrary]=await Promise.all([api('/study/library'),api('/auth/reset-config'),api('/auth/session'),api('/study/challenges')]);state.studies=library.studies||[];state.deeperStudies=(library.studies||[]).filter(item=>item.deeper);state.challenges=challengeLibrary.challenges||[];state.games=challengeLibrary.games||[];state.emailResetReady=!!config.enabled;state.user=session.user;if(state.user)await loadAccount();render()}catch(error){screen.innerHTML=`<div class="empty error">${esc(error.message)} <button class="secondary" onclick="location.reload()">Try again</button></div>`}}
function msbGitHubPages(){try{return /(^|\.)github\.io$/i.test(location.hostname)}catch{return false}}
