function msbEmptyProfile(){return {id:'local',name:'',handle:'',city:'',bio:'',email:'',denomination:'',registered:false,avatar_key:null,cover_key:null,avatar_data:null,cover_data:null}}
function msbEmptyStore(){return {profile:msbEmptyProfile(),passwordHash:null,passwordSalt:null,recoveryHash:null,emailCodeHash:null,signedOut:true,progress:[],notes:[],challenges:[],highlights:[],verseNotes:[],readLog:[],achievements:{},place:null}}
function msbNormalize(store){if(!store||typeof store!=='object')store=msbEmptyStore();if(!store.profile||typeof store.profile!=='object')store.profile=msbEmptyProfile();const p=store.profile;for(const key of ['name','handle','city','bio','email','denomination'])if(typeof p[key]!=='string')p[key]='';p.denomination=denominationShown(p.denomination);if(!p.id)p.id='local';delete p.avatar_saint;for(const key of ['progress','notes','challenges','highlights','verseNotes','readLog'])if(!Array.isArray(store[key]))store[key]=[];if(!store.achievements||typeof store.achievements!=='object')store.achievements={};/* The first standalone build seeded a default owner profile with no password (its store still carries recovery_code). Clear it so the person signs up for real. */const seeded=!store.password&&!store.passwordHash&&Object.prototype.hasOwnProperty.call(store,'recovery_code')&&p.registered===true&&!p.email;if(seeded){p.name='';p.handle='';p.email='';p.registered=false;store.password=null;store.signedOut=true}if(!store.password&&!store.passwordHash){store.signedOut=true;p.registered=false}else if(store.signedOut!==true&&store.signedOut!==false)store.signedOut=false;return store}
