let msbLibraryCache=null,msbChallengesCache=null,msbTriviaCache=null;
async function msbBundled(url){const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error(`Bundled content is missing (${res.status}).`);return res.json()}
function msbCode(length){const chars='ABCDEFGHJKMNPQRSTUVWXYZ23456789';let out='';for(let i=0;i<length;i++)out+=chars[Math.floor(Math.random()*chars.length)];return out}
function msbImageData(file,max){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',0.85))}catch(error){reject(error)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('That photo could not be read.'))};img.src=url})}
