/* Only the first remote call probes for a backend. Calls made while it is in
   flight (boot fires four at once) wait for it, so a static host sees one
   /api request instead of four. */
async function api(path,method='GET',body){if(MSB_LOCAL)return localApi(path,method,body);if(msbApiProbe){await msbApiProbe;if(MSB_LOCAL)return localApi(path,method,body)}const attempt=(async()=>{try{return await apiRemote(path,method,body)}catch(error){if(error?.status===404||error?.status===501||error?.offline||error?.invalid){MSB_LOCAL=true;return localApi(path,method,body)}throw error}})();if(!msbApiProbe)msbApiProbe=attempt.then(()=>{},()=>{});return attempt}

/* PWA: offline shell + install support */
let msbReloaded=false;function msbFreshReload(){if(msbReloaded)return;msbReloaded=true;location.reload()}
