/* Online friends (friends API on Cloudflare Workers + KV) */
const MSB_FRIENDS_KEY='msb_friends_id',MSB_FRIENDS_LIST_KEY='msb_friends_list',MSB_FRIEND_REQUESTS_KEY='msb_friend_requests';
const MSB_SHOWS=['jeopardy','millionaire','feud','sound','babel','defend','doctrine'];
const MSB_SHOW_LABEL={jeopardy:'Jeopardy',millionaire:'Millionaire',feud:'Family Feud',sound:'Sound It Out',babel:'Tower of Babel',defend:'Defend the Faith',doctrine:'Say It Right'};
function msbFriendsId(){try{const v=JSON.parse(localStorage.getItem(MSB_FRIENDS_KEY));return v&&v.code&&v.secret?v:null}catch{return null}}
function msbPublicStats(stats){const src=stats&&typeof stats==='object'&&!Array.isArray(stats)?stats:{};const bests={},levels={};for(const show of MSB_SHOWS){bests[show]=Number(src.bests&&src.bests[show])||0;levels[show]=Number(src.levels&&src.levels[show])||0}return{bests,levels,studies:Math.max(0,Math.floor(Number(src.studies)||0))}}
function msbFriendRecord(friend){if(!friend||typeof friend!=='object'||Array.isArray(friend))return null;const extra=friend.profile&&typeof friend.profile==='object'&&!Array.isArray(friend.profile)?friend.profile:{};const text=key=>{const a=typeof friend[key]==='string'?friend[key].trim():'';const b=typeof extra[key]==='string'?extra[key].trim():'';return a||b};const code=typeof friend.code==='string'?friend.code.trim():'';if(!code)return null;const view={code,name:typeof friend.name==='string'?friend.name.trim():'',updatedAt:Number(friend.updatedAt)||0,unread:Math.max(0,Math.floor(Number(friend.unread)||0)),stats:msbPublicStats(friend.stats)};const profile={};for(const key of ['handle','city','bio','denomination']){const value=text(key);if(value){view[key]=value;profile[key]=value}}for(const key of ['avatar_data','cover_data']){const value=msbPublicImage(friend[key])||msbPublicImage(extra[key]);if(value){view[key]=value;profile[key]=value}}if(Object.keys(profile).length)view.profile=profile;return view}
function msbFriendsCached(){try{const raw=JSON.parse(localStorage.getItem(MSB_FRIENDS_LIST_KEY));const rows=Array.isArray(raw)?raw.map(msbFriendRecord).filter(Boolean):[];const next=JSON.stringify(rows);if(JSON.stringify(raw)!==next){try{localStorage.setItem(MSB_FRIENDS_LIST_KEY,next)}catch{}}return rows}catch{try{localStorage.removeItem(MSB_FRIENDS_LIST_KEY)}catch{}return[]}}
function msbFriendsStats(){const store=msbStore();let prog={};try{prog=JSON.parse(localStorage.getItem('msb_gx_progress'))||{}}catch{}const scores=store.gameScores&&typeof store.gameScores==='object'&&!Array.isArray(store.gameScores)?store.gameScores:{};const levels={},bests={};for(const show of MSB_SHOWS){levels[show]=Array.isArray(prog[show]?.done)?prog[show].done.length:0;const best=Number(scores[show]&&scores[show].best);bests[show]=Number.isFinite(best)&&best>0?Math.floor(best):0}return{bests,levels,studies:store.progress.filter(row=>row.completed_at).length}}
async function msbFriendsCall(path,body){const res=await fetch(msbFriendsApi()+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});let data=null;try{data=await res.json()}catch{}if(!res.ok){const failure=Error((data&&data.error)||'The friends server did not answer.');failure.status=res.status;throw failure}return data}
window.msbFriendsCall=msbFriendsCall;window.msbFriendsId=msbFriendsId;window.msbFriendsFetch=msbFriendsFetch;window.msbFriendsCached=msbFriendsCached;window.msbCloseDialog=closeDialog;window.msbDialogHtml=function(html){overlay.hidden=false;$('#dialog-content').innerHTML=html;if(window.MsbI18n)MsbI18n.apply($('#dialog-content'))};window.msbOpenBibleVerse=function(book,chapter,verse){BibleReader.open(book,chapter,verse);nav('bible')};
function msbPublicImage(value){const raw=String(value??'').trim();if(/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/]+={0,2}$/i.test(raw))return raw;if(/^https:\/\/[^\s"'<>]+$/i.test(raw))return raw;return ''}
function msbFriendsPublicProfile(){const p=msbStore().profile||{},profile={};for(const key of ['handle','city','bio','denomination'])if(typeof p[key]==='string'&&p[key].trim())profile[key]=p[key].trim();const avatar=msbPublicImage(p.avatar_data),cover=msbPublicImage(p.cover_data);if(avatar)profile.avatar_data=avatar;if(cover)profile.cover_data=cover;return profile}
async function msbFriendsSync(){const id=msbFriendsId();if(!id)return;const profile=msbFriendsPublicProfile(),body={code:id.code,secret:id.secret,stats:msbFriendsStats()};const name=typeof id.name==='string'?id.name.trim():'';if(name)body.name=name;for(const key of ['handle','city','bio','denomination'])if(profile[key])body[key]=profile[key];const stored=msbStore().profile||{};const avatar=msbPublicImage(stored.avatar_data),cover=msbPublicImage(stored.cover_data);body.avatar_data=avatar||'';if(cover)body.cover_data=cover;body.avatar_saint='';try{const synced=await msbFriendsCall('/sync',body);if(synced&&typeof synced.publicId==='string'&&synced.publicId){id.publicId=synced.publicId;try{localStorage.setItem(MSB_FRIENDS_KEY,JSON.stringify(id))}catch{}}if(synced&&typeof synced.warning==='string'&&synced.warning)toast(synced.warning)}catch(error){toast(error?.message||'Could not sync your profile with friends.');throw error}}
function msbSocial(){const wrap=fn=>async(...args)=>{const id=msbFriendsId();if(!id)throw Error('Get your friend code first (Profile → Friends), then come back.');return fn(id,...args)};return{
  identity:()=>{const id=msbFriendsId();return id?{code:id.code,name:msbStore().profile?.name||id.name||'Friend',publicId:typeof id.publicId==='string'?id.publicId:''}:null},
  submitScore:wrap((id,show,score,level)=>msbFriendsCall('/scores/submit',{code:id.code,secret:id.secret,show,score,level})),
  createRoom:wrap((id,show,level)=>msbFriendsCall('/room/create',{code:id.code,secret:id.secret,show,level})),
  joinRoom:wrap((id,room)=>msbFriendsCall('/room/join',{code:id.code,secret:id.secret,room})),
  roomStart:wrap((id,room)=>msbFriendsCall('/room/start',{code:id.code,secret:id.secret,room})),
  roomScore:wrap((id,room,score,finished)=>msbFriendsCall('/room/score',{code:id.code,secret:id.secret,room,score,finished})),
  roomState:wrap((id,room)=>msbFriendsCall('/room/state',{code:id.code,secret:id.secret,room})),
  roomLeave:wrap((id,room)=>msbFriendsCall('/room/leave',{code:id.code,secret:id.secret,room})),
  publicScores:async show=>{const res=await fetch(msbFriendsApi()+'/scores?show='+encodeURIComponent(show));let data=null;try{data=await res.json()}catch{}if(!res.ok)throw Error((data&&data.error)||'Public scores are unavailable right now.');return ((data&&data.scores)||[]).map(row=>{if(!row||typeof row!=='object')return null;return {id:typeof row.id==='string'?row.id:'',name:typeof row.name==='string'?row.name:'',score:Number(row.score)||0,level:Number(row.level)||0,ts:Number(row.ts)||0}}).filter(Boolean)},
}}
async function msbFriendsFetch(){const id=msbFriendsId();if(!id)return msbFriendsCached();const list=await msbFriendsCall('/friends',{code:id.code,secret:id.secret});const rows=Array.isArray(list)?list.map(msbFriendRecord).filter(Boolean):[];try{localStorage.setItem(MSB_FRIENDS_LIST_KEY,JSON.stringify(rows))}catch{}return rows}
function msbFriendsAgo(ts){const s=Math.max(0,(Date.now()-(Number(ts)||0))/1000);if(s<90)return'active just now';if(s<5400)return`active ${Math.round(s/60)}m ago`;if(s<172800)return`active ${Math.round(s/3600)}h ago`;return`active ${Math.round(s/86400)}d ago`}
function msbFriendsChips(f){const st=f.stats||{bests:{},levels:{},studies:0};const studies=Math.max(0,Math.floor(Number(st.studies))||0);const chips=[`<span class="friend-chip">📖 ${studies} ${studies===1?'study':'studies'}</span>`];for(const show of MSB_SHOWS){const lv=Math.min(5,Math.max(0,Math.floor(Number(st.levels?.[show]))||0));if(lv>0)chips.push(`<span class="friend-chip">${MSB_SHOW_LABEL[show]} · Lv ${lv}/5</span>`)}return chips.join('')}
function msbFriendSelectHtml(list, selected){const rows=Array.isArray(list)?list:[];if(!rows.length)return '<option value="">No friends yet — add one above</option>';const chosen=selected||'';return rows.map(f=>`<option value="${esc(f.code)}" ${chosen===f.code?'selected':''}>${esc(f.name||'Friend')} (${esc(f.code)})</option>`).join('')}
function msbRefreshFriendPickers(list){for(const id of ['fn-to','sh-to']){const el=$('#'+id);if(!el)continue;el.innerHTML=msbFriendSelectHtml(list, el.value)}}
function msbFriendsListHtml(list){const rows=(Array.isArray(list)?list:[]).slice().sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));if(!rows.length)return'<p class="muted">No friends yet. When a request is accepted, you both appear here. Only you can see this list.</p>';return rows.map(f=>{const unread=Math.max(0,Math.floor(Number(f.unread))||0);return `<div class="card friend-row"><button type="button" class="friend-open" data-action="friend-open" data-code="${esc(f.code||'')}"><strong>${esc(f.name||'Friend')}</strong> <span class="muted">${esc(f.code||'')}</span>${unread?`<span class="friend-chip friend-unread">● ${unread} new message${unread===1?'':'s'}</span>`:''}<br><small class="muted">${msbFriendsAgo(f.updatedAt)}</small><div class="friend-chips">${msbFriendsChips(f)}</div></button><div class="friend-row-btns"><button class="secondary" data-action="msg-open" data-code="${esc(f.code||'')}" data-name="${esc(f.name||'Friend')}">💬 Message</button><button class="secondary" data-action="friends-remove" data-code="${esc(f.code||'')}">Remove</button></div></div>`}).join('')}
function msbFriendRequestsCached(){try{const raw=JSON.parse(localStorage.getItem(MSB_FRIEND_REQUESTS_KEY));const incoming=Array.isArray(raw?.incoming)?raw.incoming:[];const outgoing=Array.isArray(raw?.outgoing)?raw.outgoing:[];return {incoming,outgoing,supported:raw?.supported!==false}}catch{return {incoming:[],outgoing:[],supported:true}}}
function msbFriendRequestRows(rows,incoming){return (Array.isArray(rows)?rows:[]).map(row=>{const name=esc(row?.name||'Friend');if(incoming)return `<div class="card friend-row"><div><strong>${name}</strong><br><small class="muted">Wants to be friends</small></div><div class="friend-row-btns"><button class="primary" data-action="friends-accept" data-code="${esc(row?.code||'')}">Accept</button><button class="secondary" data-action="friends-decline" data-code="${esc(row?.code||'')}">Decline</button></div></div>`;return `<div class="card friend-row"><div><strong>${name}</strong><br><small class="muted">Waiting for them to accept</small></div><div class="friend-row-btns"><button class="secondary" data-action="friends-cancel" data-code="${esc(row?.code||'')}">Cancel request</button></div></div>`}).join('')}
function msbFriendRequestsHtml(box){if(box&&box.supported===false)return '<p class="muted">Friend requests appear here once the friends server is updated. Until then, sending a code still connects you right away.</p>';const incoming=msbFriendRequestRows(box?.incoming,true),outgoing=msbFriendRequestRows(box?.outgoing,false);if(!incoming&&!outgoing)return '<p class="muted">No pending requests.</p>';return `${incoming}${outgoing}`}
function msbPaintRequests(box){const el=$('#friends-requests');if(el)el.innerHTML=msbFriendRequestsHtml(box||msbFriendRequestsCached())}
async function msbFriendRequestsFetch(){const id=msbFriendsId();if(!id)return {incoming:[],outgoing:[],supported:false};try{const box=await msbFriendsCall('/friend/requests',{code:id.code,secret:id.secret});const next={incoming:Array.isArray(box?.incoming)?box.incoming:[],outgoing:Array.isArray(box?.outgoing)?box.outgoing:[],supported:true};try{localStorage.setItem(MSB_FRIEND_REQUESTS_KEY,JSON.stringify(next))}catch{}return next}catch(error){if(error&&(error.status===404||error.status===400))return {incoming:[],outgoing:[],supported:false};throw error}}
function friendText(record,key){const extra=record&&record.profile&&typeof record.profile==='object'?record.profile:null;const value=record&&typeof record[key]==='string'?record[key]:extra&&typeof extra[key]==='string'?extra[key]:'';return String(value||'').trim()}
function friendImage(record,...keys){const extra=record&&record.profile&&typeof record.profile==='object'?record.profile:null;for(const key of keys){const src=safeImageSrc(record&&record[key])||safeImageSrc(extra&&extra[key]);if(src)return src}return ''}
function friendProfileScreen(code){const f=(msbFriendsCached()||[]).find(item=>item&&item.code===code);if(!f){toast('That friend is not in the list on this device.');openFriends();return}state.screen='friend';state.friendCode=code;document.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav==='profile'));const name=friendText(f,'name')||'Friend',handle=friendText(f,'handle'),city=friendText(f,'city'),bio=friendText(f,'bio'),denomination=denominationShown(friendText(f,'denomination')),avatar=friendImage(f,'avatar_data','avatar','avatarUrl'),cover=friendImage(f,'cover_data','cover','coverUrl');screen.innerHTML=`<button class="text-button back" data-action="friends">← Friends</button><span class="eyebrow">FRIEND</span><div class="profile-cover">${cover?`<img src="${cover}" alt="">`:''}</div><div class="profile-head"><div class="profile-avatar friend-profile-avatar">${avatar?`<img src="${avatar}" alt="">`:esc(name[0]||'F')}</div><div><h1>${esc(name)}</h1>${handle?`<p>@${esc(handle)}</p>`:''}${city?`<p class="muted">${esc(city)}</p>`:''}</div></div>${bio?`<p class="lead">${esc(bio)}</p>`:''}${denomination?`<p class="profile-denomination">${esc(denomination)}</p>`:''}<p class="muted">Friend code ${esc(f.code||'')}. ${msbFriendsAgo(f.updatedAt)}.</p><div class="friend-chips">${msbFriendsChips(f)}</div><p><button class="secondary" data-action="msg-open" data-code="${esc(f.code||'')}" data-name="${esc(name)}">Message</button> <button class="secondary" data-action="friends">Back to friends</button></p>`;window.scrollTo({top:0,behavior:'auto'})}
function friendsScreen(){const id=msbFriendsId(),p=msbStore().profile||{};if(!id){screen.innerHTML=`<span class="eyebrow">FRIENDS</span><h1>Study and play together</h1><p class="lead">Get a friend code and share it. The other person sends a request, and you accept it before you are friends. You will see each other's studies finished and game levels beaten. Your notes stay private unless you choose to send one to a friend. Only you can see your friends list.</p><section class="card"><p><label for="friends-name">Your name for friends</label></p><p><input id="friends-name" class="text-input" type="text" value="${esc(p.name||'Friend')}" maxlength="40" autocomplete="nickname"></p><button class="primary" data-action="friends-register">Get my friend code</button><p class="muted">Works only with an internet connection; everything else in the app still works offline.</p></section><p><button class="secondary" data-nav="profile">Back to profile</button></p>`;return}let draft=null;try{draft=JSON.parse(localStorage.getItem(MSB_NOTE_DRAFT_KEY))}catch{}const friends=msbFriendsCached();const friendOpts=msbFriendSelectHtml(friends, draft&&draft.to);const studyOpts=['<option value="">No study attached</option>'].concat((Array.isArray(state.studies)?state.studies:[]).map(s=>`<option value="${esc(s.id)}" ${draft&&draft.studyId===s.id?'selected':''}>${esc(s.title)} — ${esc(s.reference)}</option>`)).join('');const banner=draft&&draft.body?`<p class="muted">📝 Carrying your note from “${esc(draft.title||'a study')}” — it is already in the box below. <button class="secondary" data-action="friends-draft-clear">Discard draft</button></p>`:'';screen.innerHTML=`<span class="eyebrow">FRIENDS</span><h1>Your friend code</h1><p><button class="secondary" data-nav="study-together">Study together</button> <button class="secondary" data-nav="verses">Verses for you</button></p><section class="card"><p class="friend-code">${esc(id.code)}</p><p class="muted">Share this code with someone you want to study with. They send a request, and you accept it here before you are friends. A private secret is stored in this browser and sent to the friends server with your requests so it can recognize you. It is not shown here, and it is not your study password. Only you can see your friends list.</p><p><button class="primary" data-action="friends-copy">Copy code</button> <button class="secondary" data-action="friends-share">Share</button></p></section><section class="card"><span class="eyebrow">SEND A REQUEST</span><p><label for="friends-add-code">Their friend code</label></p><p><input id="friends-add-code" class="text-input" type="text" placeholder="MSB-XXXXXX" autocapitalize="characters" autocomplete="off"></p><button class="primary" data-action="friends-add">Send request</button></section><h2>Requests</h2><div id="friends-requests">${msbFriendRequestsHtml(msbFriendRequestsCached())}</div><h2>Friends <button class="secondary" data-action="friends-refresh">Refresh</button></h2><div id="friends-list">${msbFriendsListHtml(msbFriendsCached())}</div><section class="card"><span class="eyebrow">SEND A NOTE TO A FRIEND</span><p class="muted">Only the note you write here is sent — your journal itself stays private on your device. Attach the study and its verse travels with the note: your friend can open the passage in the Bible and save the note straight into their own journal.</p>${banner}<p><select id="fn-to" class="text-input">${friendOpts}</select></p><p><select id="fn-study" class="text-input">${studyOpts}</select></p><p><input id="fn-title" class="text-input" type="text" maxlength="120" placeholder="Title (optional)" value="${esc(draft?.title||'')}"></p><p><textarea id="fn-body" class="note-field" maxlength="4000" rows="4" placeholder="Encouragement, a question, what the passage showed you…">${esc(draft?.body||'')}</textarea></p><button class="primary" data-action="friends-note-send">Send note</button></section><section class="card"><span class="eyebrow">SHARED NOTES — MAKE THEM TOGETHER</span><p class="muted">Start a note with a friend and you can both keep writing it. Every edit shows who made it. Attach the study and its verse travels with the note, and either of you can save a copy onto that verse in your own Bible.</p><p><select id="sh-to" class="text-input">${friendOpts}</select></p><p><select id="sh-study" class="text-input">${studyOpts}</select></p><p><input id="sh-title" class="text-input" type="text" maxlength="120" placeholder="Title (optional)"></p><p><textarea id="sh-body" class="note-field" maxlength="4000" rows="3" placeholder="Start the note together…"></textarea></p><button class="primary" data-action="shared-create">Start a shared note</button></section><h2>Shared with you</h2><div id="friends-shared">${msbSharedHtml(msbSharedCached())}</div><h2>Notes from friends</h2><div id="friends-notes">${msbFriendsNotesHtml(msbFriendsNotesCached())}</div><p><button class="secondary" data-nav="profile">Back to profile</button></p>`}
function openFriends(){msbStopMsgPoll();if(state.screen==='bible')BibleReader.hide();if(window.BibleGames)BibleGames.hide();state.screen='friends';document.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav==='profile'));friendsScreen();window.scrollTo({top:0,behavior:'auto'});msbFriendsSync().catch(()=>{});msbFriendsFetch().then(list=>{const el=$('#friends-list');if(el)el.innerHTML=msbFriendsListHtml(list);msbRefreshFriendPickers(list)}).catch(()=>{});msbFriendRequestsFetch().then(box=>msbPaintRequests(box)).catch(()=>{});msbFriendsNotesFetch().then(b=>msbRenderNotes(b)).catch(()=>{});msbSharedFetch().then(()=>{const el=$('#friends-shared');if(el)el.innerHTML=msbSharedHtml(msbSharedCached())}).catch(()=>{})}
const MSB_FRIENDS_NOTES_KEY='msb_friends_notes',MSB_NOTE_DRAFT_KEY='msb_note_draft';
function msbFriendsNotesCached(){try{const v=JSON.parse(localStorage.getItem(MSB_FRIENDS_NOTES_KEY));return v&&Array.isArray(v.inbox)?v:{inbox:[],sent:[]}}catch{return{inbox:[],sent:[]}}}
async function msbFriendsNotesFetch(){const id=msbFriendsId();if(!id)return msbFriendsNotesCached();const box=await msbFriendsCall('/notes',{code:id.code,secret:id.secret});try{localStorage.setItem(MSB_FRIENDS_NOTES_KEY,JSON.stringify(box))}catch{}return box}
let msbBibleIndexPromise=null;
function msbBibleIndex(){if(!msbBibleIndexPromise)msbBibleIndexPromise=fetch('bible/index.json').then(r=>r.json()).catch(()=>null);return msbBibleIndexPromise}
async function msbRefTarget(reference){const text=String(reference||'').split(';')[0].trim();const m=text.match(/^(.+?)\s+(\d+)(?:\((\d+)\))?(?::(\d+))?/);if(!m)return null;const idx=await msbBibleIndex();if(!idx||!Array.isArray(idx.books))return null;const want=m[1].trim().toLowerCase();const book=idx.books.find(b=>b.name.toLowerCase()===want)||idx.books.find(b=>b.name.toLowerCase()===want+'s')||idx.books.find(b=>b.name.toLowerCase()===want.replace(/s$/,''));if(!book)return null;const paren=m[3]?Number(m[3]):0,leading=Number(m[2]);const chapter=/^psalms?$/.test(want)&&paren?paren:leading;const start=book.chapterStart||1;if(!Number.isInteger(chapter)||chapter<start||chapter>book.chapters)return null;return{book:book.id,chapter,verse:m[4]?Number(m[4]):0,label:text}}
function msbNoteWhen(ts){const d=new Date(ts||0);if(isNaN(d))return'';return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · '+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}
function msbNoteCard(n,box){const mine=box==='sent';const friendName=code=>(msbFriendsCached().find(f=>f.code===code)||{}).name||code||'';const esNote=window.MsbI18n&&MsbI18n.lang()==='es';const head=mine?((esNote?'Para ':'To ')+esc(friendName(n.to))):((esNote?'De ':'From ')+esc(n.fromName||friendName(n.from)||(esNote?'Amigo':'Friend')));const item=n.studyId?study(n.studyId):null;const refBook=Math.max(0,Math.floor(Number(n.ref&&n.ref.book))||0),refChapter=Math.max(0,Math.floor(Number(n.ref&&n.ref.chapter))||0),refVerse=Math.max(0,Math.floor(Number(n.ref&&n.ref.verse))||0);return `<div class="card friend-note${!mine&&!n.read?' friend-note-new':''}"><div class="friend-note-head"><strong>${esc(n.title||(item?item.title:'A note'))}</strong>${!mine&&!n.read?'<span class="friend-chip">● New</span>':''}</div><small class="muted">${head} · ${msbNoteWhen(n.ts)}</small>${n.ref&&n.ref.label?`<p><span class="friend-chip">📖 ${esc(n.ref.label)}</span></p>`:''}<p class="friend-note-body">${esc(n.body||'')}</p><div class="note-actions">${refBook&&refChapter?`<button class="secondary" data-action="friends-note-verse" data-id="${esc(n.id)}" data-book="${refBook}" data-chapter="${refChapter}" data-verse="${refVerse||''}">Open the verse</button>`:''}${!mine&&refBook&&refChapter&&refVerse?`<button class="secondary" data-action="friends-note-verse-save" data-id="${esc(n.id)}">Save to the verse &amp; edit</button>`:''}${item?`<button class="secondary" data-lesson="${esc(item.id)}">Open the study</button>`:''}${!mine?`<button class="secondary" data-action="friends-note-save" data-id="${esc(n.id)}">Save to my notes</button><button class="secondary" data-action="friends-note-reply" data-id="${esc(n.id)}">Reply</button>`:''}<button class="secondary" data-action="friends-note-del" data-id="${esc(n.id)}" data-box="${esc(box)}">Delete</button></div></div>`}
function msbFriendsNotesHtml(box){const b=box||msbFriendsNotesCached();const inbox=Array.isArray(b.inbox)?b.inbox:[],sent=Array.isArray(b.sent)?b.sent:[];return `${inbox.length?inbox.map(n=>msbNoteCard(n,'inbox')).join(''):'<p class="muted">No notes yet. When a friend sends you one, it lands here — with its verse and study attached.</p>'}${sent.length?`<h3>Sent by you</h3>${sent.map(n=>msbNoteCard(n,'sent')).join('')}`:''}`}
function msbRenderNotes(box){const el=$('#friends-notes');if(el)el.innerHTML=msbFriendsNotesHtml(box||msbFriendsNotesCached())}
function msbNoteMarkRead(id){const me=msbFriendsId();if(!me||!id)return;msbFriendsCall('/note/read',{code:me.code,secret:me.secret,id}).catch(()=>{})}
function msbNoteFind(id){const b=msbFriendsNotesCached();return (b.inbox||[]).find(n=>n.id===id)||(b.sent||[]).find(n=>n.id===id)||null}
